 <script>
 (() => {
 'use strict';
 const $=id=>document.getElementById(id), panel=$('odpc-voice'), status=$('odpc-voice-status'), input=$('odpc-voice-answer'), log=$('odpc-voice-log');
 if(!panel||!status||!input)return;
 const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 let recognition=null, speaking='',step=0,answers={},active=false,session=0,returnFocus=null;
 const languages={
 'de-DE':{ui:['Monkey Sprachassistent','Sprache','Stimmprofil','Stimme testen','Sprachausgabe verwenden','Deine Antwort','Sprechen','Antwort senden','Wiederholen','Stopp','Neu starten','Zurück','Schließen','Monkey sprechen'],questions:['Was möchtest du mit Helper Monkey erreichen? Zum Beispiel eine Webseite verwalten, Bewerbungen schreiben, ein Fahrzeug diagnostizieren oder einen Assistenten einrichten.','Welches Gerät verwendest du? Android, iPhone, Windows, Mac oder etwas anderes?','Hast du bereits ein Google-Konto oder ein anderes Konto, das du verbinden möchtest? Bitte nenne niemals Passwörter.','Möchtest du zuerst kostenlos testen oder direkt die verfügbaren Einrichtungsschritte sehen?'],preview:'Hallo, ich bin Helper Monkey. Du hörst jetzt dieses Stimmprofil.',summary:'Danke. Ich habe deine Angaben aufgenommen. Ich zeige dir jetzt den passenden nächsten Schritt. Konten und Berechtigungen müssen ausdrücklich von dir freigegeben werden.',next:'Passenden Einrichtungsweg öffnen →'},
 'en-US':{ui:['Monkey Voice Assistant','Language','Voice profile','Test voice','Use speech output','Your answer','Speak','Send answer','Repeat','Stop','Restart','Back','Close','Talk to Monkey'],questions:['What would you like to do with Helper Monkey? For example manage a website, write job applications, diagnose a vehicle or set up an assistant.','What device are you using: Android, iPhone, Windows, Mac or something else?','Do you have a Google account or another account to connect? Never share passwords.','Would you like to try it for free first or see the setup steps?'],preview:'Hello, I am Helper Monkey. This is how this voice sounds.',summary:'Thank you. Here is your next step. Connecting accounts always requires your explicit permission.',next:'Open recommended setup →'},
 'es-ES':{ui:['Asistente de voz Monkey','Idioma','Perfil de voz','Probar voz','Usar voz','Tu respuesta','Hablar','Enviar respuesta','Repetir','Detener','Reiniciar','Atrás','Cerrar','Hablar con Monkey'],questions:['¿Qué quieres conseguir con Helper Monkey? Por ejemplo, gestionar una web, preparar solicitudes de empleo, diagnosticar un vehículo o configurar un asistente.','¿Qué dispositivo utilizas: Android, iPhone, Windows, Mac u otro?','¿Tienes una cuenta de Google u otra cuenta que quieras conectar? Nunca compartas contraseñas.','¿Prefieres probarlo gratis o ver los pasos de configuración?'],preview:'Hola, soy Helper Monkey. Así suena esta voz.',summary:'Gracias. Te mostraré el siguiente paso. La conexión de cuentas requiere tu autorización expresa.',next:'Abrir configuración recomendada →'},
 'fr-FR':{ui:['Assistant vocal Monkey','Langue','Profil vocal','Tester la voix','Activer la voix','Votre réponse','Parler','Envoyer','Répéter','Arrêter','Recommencer','Retour','Fermer','Parler à Monkey'],questions:['Que souhaitez-vous faire avec Helper Monkey ? Gérer un site, préparer une candidature, diagnostiquer un véhicule ou configurer un assistant ?','Quel appareil utilisez-vous : Android, iPhone, Windows, Mac ou autre ?','Avez-vous un compte Google ou un autre compte à connecter ? Ne partagez jamais de mot de passe.','Préférez-vous essayer gratuitement ou consulter les étapes de configuration ?'],preview:'Bonjour, je suis Helper Monkey. Voici cette voix.',summary:'Merci. Voici la prochaine étape. Toute connexion de compte nécessite votre autorisation explicite.',next:'Ouvrir la configuration →'},
 'it-IT':{ui:['Assistente vocale Monkey','Lingua','Profilo vocale','Prova voce','Usa la voce','La tua risposta','Parla','Invia','Ripeti','Ferma','Ricomincia','Indietro','Chiudi','Parla con Monkey'],questions:['Cosa vuoi fare con Helper Monkey? Gestire un sito, preparare candidature, diagnosticare un veicolo o configurare un assistente?','Quale dispositivo usi: Android, iPhone, Windows, Mac o altro?','Hai un account Google o un altro account da collegare? Non condividere password.','Vuoi provare gratuitamente o vedere i passaggi di configurazione?'],preview:'Ciao, sono Helper Monkey. Questa è la voce selezionata.',summary:'Grazie. Ecco il prossimo passo. Per collegare gli account serve la tua autorizzazione esplicita.',next:'Apri la configurazione →'},
 'pt-PT':{ui:['Assistente de voz Monkey','Idioma','Perfil de voz','Testar voz','Usar voz','A sua resposta','Falar','Enviar','Repetir','Parar','Reiniciar','Voltar','Fechar','Falar com Monkey'],questions:['O que pretende fazer com o Helper Monkey? Gerir um site, preparar candidaturas, diagnosticar um veículo ou configurar um assistente?','Que dispositivo utiliza: Android, iPhone, Windows, Mac ou outro?','Tem uma conta Google ou outra conta para ligar? Nunca partilhe palavras-passe.','Prefere experimentar gratuitamente ou ver os passos de configuração?'],preview:'Olá, sou o Helper Monkey. Esta é a voz selecionada.',summary:'Obrigado. Eis o próximo passo. A ligação de contas exige a sua autorização explícita.',next:'Abrir configuração →'},
 'pl-PL':{ui:['Asystent głosowy Monkey','Język','Profil głosu','Test głosu','Włącz głos','Twoja odpowiedź','Mów','Wyślij','Powtórz','Stop','Od nowa','Wstecz','Zamknij','Porozmawiaj z Monkey'],questions:['Co chcesz zrobić z Helper Monkey? Zarządzać stroną, przygotować CV, diagnozować samochód czy skonfigurować asystenta?','Jakiego urządzenia używasz: Android, iPhone, Windows, Mac czy innego?','Czy masz konto Google lub inne konto do połączenia? Nigdy nie podawaj haseł.','Chcesz najpierw przetestować za darmo czy zobaczyć instrukcję konfiguracji?'],preview:'Cześć, jestem Helper Monkey. Tak brzmi ten głos.',summary:'Dziękuję. Oto kolejny krok. Połączenie kont wymaga wyraźnej zgody.',next:'Otwórz konfigurację →'},
 'tr-TR':{ui:['Monkey Sesli Asistan','Dil','Ses profili','Sesi dene','Sesli yanıt','Yanıtınız','Konuş','Gönder','Tekrarla','Durdur','Yeniden başlat','Geri','Kapat','Monkey ile konuş'],questions:['Helper Monkey ile ne yapmak istiyorsunuz? Web sitesi yönetmek, iş başvurusu hazırlamak, araç arızası teşhis etmek veya asistan kurmak mı?','Hangi cihazı kullanıyorsunuz: Android, iPhone, Windows, Mac veya başka bir cihaz mı?','Bağlamak istediğiniz bir Google hesabınız veya başka hesabınız var mı? Şifre paylaşmayın.','Önce ücretsiz denemek mi yoksa kurulum adımlarını görmek mi istersiniz?'],preview:'Merhaba, ben Helper Monkey. Seçtiğiniz ses böyle duyuluyor.',summary:'Teşekkürler. Sıradaki adım burada. Hesap bağlantıları açık izninizi gerektirir.',next:'Kurulumu aç →'}
 };
 const uiIds=['odpc-voice-title','label-language','label-persona','odpc-voice-preview','label-audio','label-answer','odpc-voice-mic','odpc-voice-send','odpc-voice-repeat','odpc-voice-stop','odpc-voice-reset','odpc-voice-back','odpc-voice-close','odpc-voice-open'];
 const questions=()=>languages[$('odpc-voice-language').value].questions.map((q,i)=>[['goal','device','account','mode'][i],q]);
 function localize(){const l=languages[$('odpc-voice-language').value];uiIds.forEach((id,i)=>{const el=$(id);if(el){if(id==='label-audio'){const cb=$('odpc-voice-audio');el.replaceChildren(cb,document.createTextNode(' '+l.ui[i]))}else el.textContent=(i===0?'🐵 ':i===13?'🎙 ':'')+l.ui[i]}});$('odpc-voice-topclose').setAttribute('aria-label',l.ui[12]);document.documentElement.lang=document.documentElement.lang||'de';if(active){stopAudio();step=0;answers={};log.replaceChildren();panel.dataset.finished='no';input.disabled=false;$('odpc-voice-send').disabled=false;$('odpc-voice-mic').disabled=false;ask();}}

 let voiceCatalog=[],speechTicket=0;
 function voiceGender(v){const n=(v.name||'').toLowerCase();if(/\b(male|man|masculine|männlich|hombre|homme|uomo|masculino)\b|\b(david|mark|daniel|george|thomas|stefan|paul|alexander|jorge|diego|pablo|carlos|enrique|conrad|christoph|stefano|henri|guy|andrew|ryan|matthew|liam|oliver|brian)\b/.test(n))return 'male';if(/\b(female|woman|feminine|weiblich|mujer|femme|donna|femenino)\b|\b(anna|sarah|samantha|victoria|karen|helena|maria|monica|lucia|sofia|laura|katja|heda|sabine|zira|jenny|aria|hazel|emma|amy|susan|julie|amelie)\b/.test(n))return 'female';return 'unknown'}
 function refreshVoices(){const select=$('odpc-voice-persona'),lang=$('odpc-voice-language').value.slice(0,2).toLowerCase(),filter=$('odpc-voice-gender').value,previous=voiceCatalog[Number(select.value)]?.voiceURI||'',all=('speechSynthesis' in window)?speechSynthesis.getVoices():[];voiceCatalog=all.filter(v=>(v.lang||'').toLowerCase().startsWith(lang)&& (filter==='all'||voiceGender(v)===filter));select.replaceChildren(new Option('Standard / System','auto'));voiceCatalog.forEach((v,i)=>{const name=v.name||('Stimme '+(i+1));select.add(new Option(name+' ('+v.lang+')',String(i)))});const idx=voiceCatalog.findIndex(v=>v.voiceURI===previous);select.value=idx>=0?String(idx):'auto';const count=all.filter(v=>(v.lang||'').toLowerCase().startsWith(lang)).length;$('odpc-voice-voicehelp').textContent=filter==='all'?count+' vom Browser bereitgestellte Stimmen für diese Sprache.':voiceCatalog.length?voiceCatalog.length+' anhand des Namens als '+(filter==='male'?'männlich':'weiblich')+' erkannte Stimmen.':'Keine eindeutig als '+(filter==='male'?'männlich':'weiblich')+' benannte Stimme gefunden. Bitte „Alle Stimmen“ wählen und Hörproben testen. Die Browser-API liefert keine verlässliche Geschlechtsangabe.';$('odpc-voice-preview').disabled=false;}

 function say(t){speaking=t;if(!$('odpc-voice-audio').checked)return;if(!('speechSynthesis' in window)||!window.SpeechSynthesisUtterance){status.textContent='Sprachausgabe nicht verfügbar. Text bleibt lesbar.';return}try{const ticket=++speechTicket;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang=$('odpc-voice-language').value;u.rate=1.12;const id=$('odpc-voice-persona').value;if(id!=='auto'&&voiceCatalog[Number(id)])u.voice=voiceCatalog[Number(id)];u.onerror=e=>{if(ticket!==speechTicket)return;status.textContent='Sprachausgabe nicht möglich ('+(e.error||'Gerätefehler')+'). Bitte eine andere Stimme wählen oder Chrome direkt öffnen.'};speechSynthesis.speak(u)}catch(e){status.textContent='Sprachausgabe nicht verfügbar. Bitte Text lesen.'}}
 $('odpc-voice-preview').addEventListener('click',()=>say(languages[$('odpc-voice-language').value].preview));
 $('odpc-voice-persona').addEventListener('change',()=>{speechTicket++;if('speechSynthesis' in window)speechSynthesis.cancel();status.textContent='Stimmprofil ausgewählt. Tippe auf Stimme testen.'});
 $('odpc-voice-language').addEventListener('change',()=>{refreshVoices();localize()});
 $('odpc-voice-gender').addEventListener('change',refreshVoices);
 if('speechSynthesis' in window){speechSynthesis.addEventListener?.('voiceschanged',refreshVoices);refreshVoices();setTimeout(refreshVoices,700);setTimeout(refreshVoices,2000);}localize();

 function stopAudio(){session++;speechTicket++;if(recognition){try{recognition.abort()}catch(e){}recognition=null}if('speechSynthesis' in window)speechSynthesis.cancel()}
 function append(role,t){const p=document.createElement('p');const b=document.createElement('strong');b.textContent=role+': ';p.append(b,document.createTextNode(t));log.append(p);log.scrollTop=log.scrollHeight}
 function ask(){if(panel.hidden)return;if(step>=questions().length){finish();return}const q=questions()[step][1];status.textContent='Frage '+(step+1)+' von '+questions().length;append('Monkey',q);say(q)}
 function finish(){if(panel.dataset.finished==='yes')return;panel.dataset.finished='yes';const goal=(answers.goal||'').toLowerCase();let path='/start/';if(/auto|fahrzeug|obd|motor/.test(goal))path='/start/';else if(/web|homepage|wordpress|seite/.test(goal))path='/webmaster-agent/';else if(/konto|connector|gmail|google/.test(goal))path='/connector-einrichten/';else if(/recht|anwalt|kanzlei/.test(goal))path='/konfliktlotse-anwaltsvorarbeit/';
 const summary=languages[$('odpc-voice-language').value].summary;
 append('Monkey',summary);say(summary);
 const a=document.createElement('a');a.href=path;a.textContent=languages[$('odpc-voice-language').value].next;a.style.display='block';a.style.marginTop='12px';log.append(a);
 const pre=document.createElement('p');pre.textContent='Your answers remain in this browser window; this module does not send them to a server.';log.append(pre);
 status.textContent='Interview abgeschlossen';input.disabled=true;$('odpc-voice-send').disabled=true;$('odpc-voice-mic').disabled=true;
 }
 function submit(){if(step>=questions().length)return;const value=input.value.trim().slice(0,1000);if(!value)return;append('Du',value);answers[questions()[step][0]]=value;step++;input.value='';ask()}
 $('odpc-voice-open').addEventListener('click',()=>{returnFocus=document.activeElement;panel.hidden=false;$('odpc-voice-open').setAttribute('aria-expanded','true');if(!active){active=true;ask()}refreshVoices();input.focus()});
 $('odpc-voice-topclose').addEventListener('click',()=>$('odpc-voice-close').click());
 $('odpc-voice-close').addEventListener('click',()=>{panel.hidden=true;$('odpc-voice-open').setAttribute('aria-expanded','false');stopAudio();(returnFocus&&returnFocus.isConnected?returnFocus:$('odpc-voice-open')).focus()});
 $('odpc-voice-send').addEventListener('click',submit);
 $('odpc-voice-stop').addEventListener('click',()=>{stopAudio();status.textContent='Audio gestoppt. Texteingabe ist weiterhin möglich.'});
 $('odpc-voice-reset').addEventListener('click',()=>{stopAudio();step=0;answers={};active=true;panel.dataset.finished='no';log.replaceChildren();input.value='';input.disabled=false;$('odpc-voice-send').disabled=false;$('odpc-voice-mic').disabled=false;ask();input.focus()});
 input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();submit()}});
 $('odpc-voice-repeat').addEventListener('click',()=>say(speaking));
 $('odpc-voice-back').addEventListener('click',()=>{if(step===0)return;stopAudio();if(panel.dataset.finished==='yes'){panel.dataset.finished='no';log.querySelectorAll('a[href]').forEach(a=>a.remove())}step--;delete answers[questions()[step][0]];input.disabled=false;$('odpc-voice-send').disabled=false;$('odpc-voice-mic').disabled=false;ask()});
 $('odpc-voice-mic').addEventListener('click',()=>{
  if(!SpeechRecognition){status.textContent='Spracheingabe wird hier nicht unterstützt. Bitte tippe deine Antwort.';input.focus();return}
  if(recognition){try{recognition.abort()}catch(e){}}if('speechSynthesis' in window)speechSynthesis.cancel();
  const ticket=++session;recognition=new SpeechRecognition();recognition.lang=$('odpc-voice-language').value;recognition.interimResults=false;recognition.maxAlternatives=1;
  recognition.onresult=e=>{if(ticket!==session||panel.hidden)return;input.value=e.results[0][0].transcript;status.textContent='Antwort erkannt. Du kannst sie korrigieren oder senden.';input.focus()};
  recognition.onerror=e=>{if(ticket!==session||panel.hidden)return;status.textContent='Mikrofonfehler: '+e.error+'. Bitte nutze die Texteingabe.'};
  recognition.onend=()=>{if(ticket===session)recognition=null};try{recognition.start();status.textContent='Ich höre zu …'}catch(e){status.textContent='Mikrofon konnte nicht gestartet werden.'}
 });
 document.addEventListener('keydown',e=>{if(panel.hidden)return;if(e.key==='Escape'){$('odpc-voice-close').click();return}if(e.key==='Tab'){const nodes=Array.from(panel.querySelectorAll('button:not([disabled]),input:not([disabled]),select,a[href]')).filter(el=>el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});
 })();
 </script>
